"use client";

import { useState, type FormEvent } from "react";
import { useRouter } from "next/navigation";
import { ArrowRight, HardDrive, Lock, Plus, Zap } from "lucide-react";
import { generateRoomCode } from "@/lib/crypto";

function extractRoomCode(raw: string): string | null {
  const trimmed = raw.trim();
  if (!trimmed) return null;

  const roomPathMatch = trimmed.match(/\/room\/([A-Za-z0-9_-]+)/);
  if (roomPathMatch?.[1]) {
    return roomPathMatch[1];
  }

  if (/^[A-Za-z0-9_-]{4,64}$/.test(trimmed)) {
    return trimmed;
  }

  return null;
}

export default function HomePage() {
  const router = useRouter();
  const [joinInput, setJoinInput] = useState("");
  const [error, setError] = useState<string | null>(null);

  const handleCreateRoom = () => {
    const code = generateRoomCode();
    router.push(`/room/${code}`);
  };

  const handleJoinRoom = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const code = extractRoomCode(joinInput);
    if (!code) {
      setError("Enter a valid 12-character room code or full room URL.");
      return;
    }
    setError(null);
    router.push(`/room/${code}`);
  };

  return (
    <main className="relative flex min-h-screen flex-col items-center justify-center px-4 py-12">
      <div className="pointer-events-none absolute inset-0 overflow-hidden">
        <div className="absolute left-1/2 top-1/4 h-72 w-72 -translate-x-1/2 rounded-full bg-emerald-500/10 blur-3xl" />
      </div>

      <div className="relative z-10 flex w-full max-w-lg flex-col items-center text-center">
        <div className="mb-5 inline-flex items-center gap-2 rounded-full border border-zinc-800 bg-zinc-900/80 px-3 py-1 text-xs font-medium text-zinc-400">
          <span className="h-1.5 w-1.5 rounded-full bg-emerald-400" />
          Peer-to-Peer Direct Transfer
        </div>

        <h1 className="text-4xl font-semibold tracking-tight text-zinc-50 sm:text-5xl">
          DropPeer
        </h1>
        <p className="mt-3 max-w-md text-sm text-zinc-400 sm:text-base">
          Zero-storage, end-to-end encrypted P2P file &amp; text drop
        </p>

        <div className="mt-6 flex flex-wrap items-center justify-center gap-2">
          <span className="inline-flex items-center gap-1.5 rounded-full border border-zinc-800 bg-zinc-900/70 px-3 py-1 text-xs text-zinc-300">
            <Zap className="h-3.5 w-3.5 text-emerald-400" />
            WebRTC Direct
          </span>
          <span className="inline-flex items-center gap-1.5 rounded-full border border-zinc-800 bg-zinc-900/70 px-3 py-1 text-xs text-zinc-300">
            <Lock className="h-3.5 w-3.5 text-emerald-400" />
            DTLS Encrypted
          </span>
          <span className="inline-flex items-center gap-1.5 rounded-full border border-zinc-800 bg-zinc-900/70 px-3 py-1 text-xs text-zinc-300">
            <HardDrive className="h-3.5 w-3.5 text-emerald-400" />
            0 Server Storage
          </span>
        </div>

        <div className="mt-10 w-full rounded-2xl border border-zinc-800/90 bg-zinc-900/60 p-6 shadow-2xl shadow-black/40 backdrop-blur">
          <button
            type="button"
            onClick={handleCreateRoom}
            className="flex w-full cursor-pointer items-center justify-center gap-2 rounded-xl bg-emerald-500 px-5 py-3 text-sm font-semibold text-zinc-950 transition hover:bg-emerald-400 active:scale-[0.99]"
          >
            <Plus className="h-4 w-4 stroke-[2.5]" />
            Create Room
          </button>

          <div className="my-5 flex items-center gap-3">
            <div className="h-px flex-1 bg-zinc-800" />
            <span className="text-xs uppercase tracking-wider text-zinc-500">
              or join existing
            </span>
            <div className="h-px flex-1 bg-zinc-800" />
          </div>

          <form onSubmit={handleJoinRoom} className="flex flex-col gap-2.5 sm:flex-row">
            <input
              type="text"
              value={joinInput}
              onChange={(e) => {
                setJoinInput(e.target.value);
                if (error) setError(null);
              }}
              placeholder="Paste 12-char code or room URL..."
              aria-label="Room code or URL"
              className="flex-1 rounded-xl border border-zinc-800 bg-zinc-950 px-3.5 py-2.5 text-sm text-zinc-100 placeholder-zinc-500 transition focus:border-zinc-600 focus:outline-none"
            />
            <button
              type="submit"
              className="inline-flex cursor-pointer items-center justify-center gap-1.5 rounded-xl border border-zinc-700 bg-zinc-800 px-4 py-2.5 text-sm font-medium text-zinc-100 transition hover:bg-zinc-700"
            >
              Join Room
              <ArrowRight className="h-4 w-4" />
            </button>
          </form>

          {error && (
            <p className="mt-2.5 text-left text-xs text-rose-400">{error}</p>
          )}
        </div>
      </div>
    </main>
  );
}
